def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    :param n: The highest degree of the polynomial.
    :param coeffs: A list of coefficients, starting with the coefficient of the highest degree term.
    :return: The string representation of the polynomial.
    """
    from typing import List
    if not coeffs:
        return "0"

    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue

        degree = n - i

        # Determine the sign
        if i == 0:
            # First term: no leading '+'
            if coeff < 0:
                sign = "-"
            else:
                sign = ""
        else:
            # Subsequent terms: include sign
            if coeff < 0:
                sign = "-"
            else:
                sign = "+"

        # Determine the coefficient part
        abs_coeff = abs(coeff)
        if degree > 0 and abs_coeff == 1:
            coeff_part = ""
        else:
            coeff_part = str(abs_coeff)

        # Determine the variable part
        if degree == 0:
            var_part = ""
        elif degree == 1:
            var_part = "x"
        else:
            var_part = f"x^{degree}"

        term = sign + coeff_part + var_part
        terms.append(term)

    if not terms:
        return "0"

    return "".join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    # Build the mapping from encoded to original
    mapping = {}
    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            if mapping[enc_char] != orig_char:
                return "Failed"
        else:
            mapping[enc_char] = orig_char

    # Check if the mapping is a bijection (each original char maps to exactly one encoded char)
    # We need to ensure that no two different encoded chars map to the same original char
    reverse_mapping = {}
    for enc_char, orig_char in mapping.items():
        if orig_char in reverse_mapping:
            if reverse_mapping[orig_char] != enc_char:
                return "Failed"
        else:
            reverse_mapping[orig_char] = enc_char

    # Check if all letters in the message are in the mapping
    for char in message:
        if char not in mapping:
            return "Failed"

    # Decode the message
    decoded = []
    for char in message:
        decoded.append(mapping[char])

    return ''.join(decoded)

